import{_ as i,a as n,c as l,ac as o}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第四册：流利英语 · 单元 1：从观察到判断","description":"L1–L8 的学习目标、课时入口和复习方法。","frontmatter":{"title":"第四册：流利英语 · 单元 1：从观察到判断","description":"L1–L8 的学习目标、课时入口和复习方法。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","summary":"L1–L8 的学习目标、课时入口和复习方法。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · 综合复习与自测 · 第45–48课","link":"/life/english/new-concept/book-4/review-part-05"},"next":{"text":"第四册：流利英语 · 单元 1 语法总结","link":"/life/english/new-concept/book-4/unit-01/grammar"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · 综合复习与自测 · 第45–48课","link":"/life/english/new-concept/book-4/review-part-05"},"next":{"text":"第四册：流利英语 · 单元 1 语法总结","link":"/life/english/new-concept/book-4/unit-01/grammar"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-01/overview.md","filePath":"life/english/new-concept/book-4/unit-01/overview.md"}'),a={name:"life/english/new-concept/book-4/unit-01/overview.md"};function t(s,e,r,c,h,u){return n(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-单元-1-从观察到判断" tabindex="-1">第四册：流利英语 · 单元 1：从观察到判断 <a class="header-anchor" href="#第四册-流利英语-·-单元-1-从观察到判断" aria-label="Permalink to &quot;第四册：流利英语 · 单元 1：从观察到判断&quot;">​</a></h1><p><a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-01/overview">单元导读</a> · <a href="/life/english/new-concept/book-4/unit-01/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-4/unit-01/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-4/unit-01/review">单元复习与自测</a></p><h2 id="单元导读" tabindex="-1">单元导读 <a class="header-anchor" href="#单元导读" aria-label="Permalink to &quot;单元导读&quot;">​</a></h2><p>L1–L8。第1—8课以化石、蜘蛛、山区生活、异常感知、青年、竞技、蝙蝠和商品标准为入口，练习把看到的现象、提出的解释和能够确认的结论分开。这个阶段不追求逐字翻译，而是抓住句子主干与论证范围，特别留意情态动词、数量词和信息来源。遇到历史材料中的强烈主张，先辨认作者说了什么，再问需要什么证据。</p><p>本栏目按连续课号组织学习单元；单元主题与复习任务为本站编排，便于分阶段学习，不作为各印次教材目录的替代。</p><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><ul><li>区分观察、推测和规范性要求</li><li>掌握过去推测、让步与关系从句</li><li>写出带范围限制的三句说明</li></ul><h2 id="课时目录" tabindex="-1">课时目录 <a class="header-anchor" href="#课时目录" aria-label="Permalink to &quot;课时目录&quot;">​</a></h2><ul><li><a href="/life/english/new-concept/book-4/unit-01/lesson-001">Lesson 1 · Finding fossil man</a></li><li><a href="/life/english/new-concept/book-4/unit-01/lesson-002">Lesson 2 · Spare that spider</a></li><li><a href="/life/english/new-concept/book-4/unit-01/lesson-003">Lesson 3 · Matterhorn man</a></li><li><a href="/life/english/new-concept/book-4/unit-01/lesson-004">Lesson 4 · Seeing hands</a></li><li><a href="/life/english/new-concept/book-4/unit-01/lesson-005">Lesson 5 · Youth</a></li><li><a href="/life/english/new-concept/book-4/unit-01/lesson-006">Lesson 6 · The sporting spirit</a></li><li><a href="/life/english/new-concept/book-4/unit-01/lesson-007">Lesson 7 · Bats</a></li><li><a href="/life/english/new-concept/book-4/unit-01/lesson-008">Lesson 8 · Trading standards</a></li></ul><h2 id="单元知识地图" tabindex="-1">单元知识地图 <a class="header-anchor" href="#单元知识地图" aria-label="Permalink to &quot;单元知识地图&quot;">​</a></h2><ul><li>L1：推测情态动词与过去事件。不要把 might have been made 译成“必定是造成的”；might 保留了其他解释。</li><li>L2：数量词与可数性。The number of insects were lower 错在主谓一致；但 A number of insects were found 中复数正确。</li><li>L3：used to、would 与过去状态。不要用 would be quiet 无背景地替代 used to be quiet；would 还可能被理解为条件结果。</li><li>L4：报告动词与认知距离。“was reported to identify”不是“被证实能够辨认”；reported 与 proved 的证据含义不同。</li><li>L5：让步从句与主句重心。Although she was young, but she led the discussion. 应去掉 but；despite her youth 则不需要主谓结构。</li><li>L6：not so much A as B 的纠正性对比。不要将 not so much A as B 理解成“不如 A 那么 B”；它在两个解释之间强调后者。</li><li>L7：关系从句中的指代与功能说明。不能把 the echo that returns 写成 the echo returns 后仍接在原宾语位置；省略主语关系词会破坏结构。</li><li>L8：情态动词的被动结构。every sample must checked 缺少 be；必须写 must be checked。</li></ul><h2 id="完成标准" tabindex="-1">完成标准 <a class="header-anchor" href="#完成标准" aria-label="Permalink to &quot;完成标准&quot;">​</a></h2><p>能用自己的例子说明上面的语法点；能在不看答案时完成单元自测；能完成至少一项口头表达和一项书面表达，并根据课时点评修订。若做错，不必整单元重学，沿题目链接回到相应课时。</p>',13)])])}const f=i(a,[["render",t]]);export{p as __pageData,f as default};
